// Generates src/lib/components/ui/icons.ts from the mockup sprite ui/mockups/icons.svg.
//
// The app draws each icon as inline SVG elements, so it needs no sprite request and no
// `<use>` reference under the strict policy (ADR-0027). The test icons.test.ts fails
// when the generated file and the sprite differ.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parseSprite } from './sprite.mjs';

const sprite = fileURLToPath(new URL('../mockups/icons.svg', import.meta.url));
const target = fileURLToPath(new URL('../src/lib/components/ui/icons.ts', import.meta.url));

const icons = parseSprite(readFileSync(sprite, 'utf8'));
const body = Object.entries(icons)
	.map(([name, shapes]) => `\t${JSON.stringify(name)}: ${JSON.stringify(shapes)}`)
	.join(',\n');

writeFileSync(
	target,
	`// Generated by scripts/gen-icons.mjs from ui/mockups/icons.svg. Do not edit.

export type IconShape = ['path' | 'circle' | 'rect' | 'ellipse', Record<string, string>];

export const icons = {
${body}
} satisfies Record<string, IconShape[]>;

export type IconName = keyof typeof icons;
`
);
